using System.Text.Json.Serialization;
using Twilio.Core.Enum;

namespace Twilio.Models.Enums;

/// <summary>
/// The HTTP method used to generate the notification. If the notification was generated during a phone call, this is the HTTP Method used to request the resource on your server. If the notification was generated by your use of our REST API, this is the HTTP method used to call the resource on our servers.
/// </summary>
[JsonConverter(typeof(StringEnumConverter<RequestMethod>))]
public sealed record RequestMethod : StringEnum<RequestMethod>
{
    private RequestMethod(string value) : base(value)
    {
    }

    public static readonly RequestMethod Get = new("GET");

    public static readonly RequestMethod Post = new("POST");

    public static RequestMethod FromValue(string value) => FromValueCore(value);
}
